x-codeSamples.source:
curl --request POST \
--url https://api.baseten.co/v1/models \
--header "Authorization: Bearer $BASETEN_API_KEY" \
--data '{
  "source": null
}'

curl --request PATCH \
--url https://api.baseten.co/v1/models/{model_id} \
--header "Authorization: Bearer $BASETEN_API_KEY" \
--data '{
  "name": "my-model"
}'

curl --request POST \
--url https://api.baseten.co/v1/models/{model_id}/deployments \
--header "Authorization: Bearer $BASETEN_API_KEY" \
--data '{
  "source": null
}'

curl --request POST \
--url https://api.baseten.co/v1/models/{model_id}/deployments/development/promote \
--header "Authorization: Bearer $BASETEN_API_KEY" \
--data '{
  "scale_down_previous_production": true,
  "preserve_env_instance_type": true,
  "environment_settings_update": {
    "autoscaling_settings": {
      "max_replica": 4,
      "min_replica": 2
    }
  },
  "promotion_settings_override": {
    "rolling_deploy_config": {
      "max_surge_percent": 50
    }
  }
}'

curl --request PATCH \
--url https://api.baseten.co/v1/models/{model_id}/deployments/{deployment_id} \
--header "Authorization: Bearer $BASETEN_API_KEY" \
--data '{
  "name": "my-deployment"
}'

curl --request POST \
--url https://api.baseten.co/v1/models/{model_id}/deployments/{deployment_id}/patches \
--header "Authorization: Bearer $BASETEN_API_KEY" \
--data '{
  "prev_patch_hash": null,
  "next_patch_point": {
    "content_hashes": null,
    "config": null
  },
  "patch_ops": null
}'

curl --request POST \
--url https://api.baseten.co/v1/models/{model_id}/deployments/{deployment_id}/promote \
--header "Authorization: Bearer $BASETEN_API_KEY" \
--data '{
  "scale_down_previous_production": true,
  "preserve_env_instance_type": true,
  "environment_settings_update": {
    "autoscaling_settings": {
      "max_replica": 4,
      "min_replica": 2
    }
  },
  "promotion_settings_override": {
    "rolling_deploy_config": {
      "max_surge_percent": 50
    }
  }
}'

curl --request PATCH \
--url https://api.baseten.co/v1/models/{model_id}/deployments/{deployment_id}/request_backpressure_settings \
--header "Authorization: Bearer $BASETEN_API_KEY" \
--data '{
  "policy": "REJECT_ON_FULL"
}'

curl --request PATCH \
--url https://api.baseten.co/v1/models/{model_id}/environments/{env_name} \
--header "Authorization: Bearer $BASETEN_API_KEY" \
--data '{
  "autoscaling_settings": {
    "autoscaling_window": 800,
    "concurrency_target": 3,
    "max_replica": 2,
    "max_scale_down_rate": null,
    "min_replica": 1,
    "scale_down_delay": 60,
    "target_in_flight_tokens": null,
    "target_utilization_percentage": null
  },
  "promotion_settings": {
    "promotion_cleanup_strategy": null,
    "ramp_up_duration_seconds": null,
    "ramp_up_while_promoting": null,
    "redeploy_on_promotion": true,
    "rolling_deploy": true,
    "rolling_deploy_config": null
  },
  "autoscaling_schedule_settings": {
    "schedules": [
      {
        "autoscaling_settings": {
          "autoscaling_window": null,
          "concurrency_target": null,
          "max_replica": 8,
          "max_scale_down_rate": null,
          "min_replica": 2,
          "scale_down_delay": null,
          "target_in_flight_tokens": null,
          "target_utilization_percentage": null
        },
        "cadence": "DAILY",
        "enabled": true,
        "end_hour": 10,
        "end_minute": 0,
        "name": "weekday-peak",
        "start_hour": 8,
        "start_minute": 0,
        "weekdays": [
          "MONDAY",
          "TUESDAY",
          "WEDNESDAY",
          "THURSDAY",
          "FRIDAY"
        ]
      }
    ],
    "timezone": "America/Los_Angeles"
  },
  "request_backpressure_settings": {
    "policy": "REJECT_ON_FULL"
  },
  "traffic_routing_settings": {
    "rules": [
      {
        "expires_at": "2026-10-13T18:00:00Z",
        "percent_traffic": 25,
        "propagate_client_cancellation": true,
        "sampling_mode": "USER_SESSION",
        "targets": [
          {
            "deployment_id": "abc123"
          }
        ],
        "type": "SHADOW"
      }
    ]
  }
}'

curl --request POST \
--url https://api.baseten.co/v1/models/{model_id}/environments/{env_name}/promote \
--header "Authorization: Bearer $BASETEN_API_KEY" \
--data '{
  "scale_down_previous_deployment": true,
  "deployment_id": null,
  "preserve_env_instance_type": true,
  "environment_settings_update": {
    "autoscaling_settings": {
      "max_replica": 4,
      "min_replica": 2
    }
  },
  "promotion_settings_override": {
    "rolling_deploy_config": {
      "max_surge_percent": 50
    }
  }
}'

curl --request POST \
--url https://api.baseten.co/v1/prepare_model_upload \
--header "Authorization: Bearer $BASETEN_API_KEY" \
--data '{
  "deployment": {
    "config": null,
    "raw_config": null,
    "user_env": null,
    "environment_name": null,
    "region": null,
    "deploy_timeout_minutes": null,
    "deployment_name": null,
    "labels": null,
    "autoscaling_settings": {
      "max_replica": 4,
      "min_replica": 2
    },
    "request_backpressure_settings": {
      "policy": "REJECT_ON_FULL"
    },
    "autoscaling_schedule_settings": null,
    "promotion_settings_override": {
      "rolling_deploy_config": {
        "max_surge_percent": 50
      }
    },
    "instance_type_id": null
  },
  "name": null,
  "team_id": null,
  "model_id": null
}'

AuditLogEventEnvironmentSettingsV1.description:
Full environment settings (autoscaling + rolling promotion + deprecated canary);
shared base for the environment events and the type of their previous_settings
snapshots. Not itself a payload in the discriminated union.
